import pw from 'file:///D:/repository/苏住房G/node_modules/playwright-core/index.js';
const { chromium } = pw;
const exe = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe';
const BASE = 'http://127.0.0.1:8108';

// Synthetic menu: Layout > 系统监控 > 综合大屏 ; Layout > 物业管理 > 物业管理区域备案(目标)
const routers = [
  {
    path: '/system', component: 'Layout', name: 'System', meta: { title: '系统' },
    children: [
      {
        path: 'monitor', component: 'ParentView', name: 'Monitor', meta: { title: '系统监控' },
        children: [
          { path: 'smartPropertyScreen', name: 'SmartPropertyScreen', component: 'smartPropertyScreen/index', meta: { title: '综合大屏' } }
        ]
      }
    ]
  },
  {
    path: '/property', component: 'Layout', name: 'Property', meta: { title: '物业管理' },
    children: [
      { path: 'complex/complex', name: 'PropertyComplex', component: 'property/complex/index', meta: { title: '物业管理区域备案' } }
    ]
  }
];

(async () => {
  const browser = await chromium.launch({ executablePath: exe, headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 900 } });
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('PAGEERR ' + e.message));

  // intercept API
  await page.route('**/api/v2.0/**', async (route) => {
    const url = route.request().url();
    const json = (obj) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(obj) });
    if (url.includes('/system/user/getInfo')) {
      return json({ code: 200, user: { userName: 'test', nickName: '测试', terminalType: 'A', deptId: 1, deptName: 'x' }, roles: ['admin'], permissions: ['*:*:*'] });
    }
    if (url.includes('/system/profile')) {
      return json({ code: 200, data: { dept: { deptName: 'x' }, parentDept: { deptName: 'y' } } });
    }
    // default generic success
    return json({ code: 200, data: {}, rows: [], total: 0 });
  });

  // seed session BEFORE app loads
  await page.addInitScript((routers) => {
    sessionStorage.setItem('Admin-Token', 'fake-token-e2e');
    sessionStorage.setItem('routers', JSON.stringify(routers));
  }, routers);

  await page.goto(BASE + '/#/system/monitor/smartPropertyScreen', { waitUntil: 'domcontentloaded', timeout: 30000 }).catch(e=>console.log('goto', e.message));
  await page.waitForTimeout(5000);

  // wait for the 综合大屏 tab to appear
  const tabSel = '.tags-view-item';
  await page.waitForSelector(tabSel, { timeout: 15000 }).catch(()=>{});
  let tabs = await page.$$eval(tabSel, els => els.map(e => e.querySelector('.title')?.textContent.trim()));
  console.log('TABS_INITIAL', JSON.stringify(tabs));

  // enter fullscreen
  await page.evaluate(() => document.querySelector('.tags-view-item') && null);
  // click 全屏 button on the screen page
  const fsBtn = await page.$('text=全屏');
  console.log('HAS_FS_BTN', !!fsBtn);
  if (fsBtn) { await fsBtn.click(); }
  await page.waitForTimeout(1500);
  const inFullscreen = await page.evaluate(() => document.querySelector('.app-wrapper')?.classList.contains('content-fullscreen'));
  console.log('IN_FULLSCREEN', inFullscreen);
  const tagsVisibleInFs = await page.evaluate(() => {
    const el = document.querySelector('#tags-view-container');
    if (!el) return 'ABSENT';
    const cs = getComputedStyle(el);
    return cs.display;
  });
  console.log('TAGSVIEW_DISPLAY_IN_FS', tagsVisibleInFs);

  // drill-through: click first statistic card (物业管理区域总数) -> should navigate to target
  // In screen, clicking cards triggers goMenu; find a clickable stat
  const clicked = await page.evaluate(() => {
    const nodes = [...document.querySelectorAll('*')].filter(n => /物业管理区域总数/.test(n.textContent||'') && n.children.length===0);
    return nodes.length;
  });
  console.log('STAT_MATCH', clicked);
  // Try clicking the card container
  const card = await page.$('text=物业管理区域总数');
  if (card) {
    try { await card.click({ timeout: 3000 }); } catch(e){ console.log('click card err', e.message); }
  }
  await page.waitForTimeout(4000);
  console.log('URL_AFTER_DRILL', page.url());
  tabs = await page.$$eval(tabSel, els => els.map(e => e.querySelector('.title')?.textContent.trim())).catch(()=>[]);
  console.log('TABS_AFTER_DRILL', JSON.stringify(tabs));
  const hasScreenTab = tabs.some(t => t && t.includes('综合大屏'));
  console.log('SCREEN_TAB_PERSISTS', hasScreenTab);
  await page.screenshot({ path: 'D:/repository/榆林G/pw_e2e_after.png' });
  console.log('ERRORS', JSON.stringify(errs.slice(0,5)));
  await browser.close();
})();

