import pw from 'file:///D:/repository/苏住房G/node_modules/playwright-core/index.js';
const { chromium } = pw;
const exe = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe';
const BASE = 'http://127.0.0.1:8108';
const routers = [
  { path: '/system', component: 'Layout', name: 'System', meta: { title: '系统' }, children: [
    { path: 'monitor', component: 'ParentView', name: 'Monitor', meta: { title: '系统监控' }, children: [
      { path: 'smartPropertyScreen', name: 'SmartPropertyScreen', component: 'smartPropertyScreen/index', meta: { title: '综合大屏', filePath: 'smartPropertyScreen/index' } } ] } ] },
  { path: '/property', component: 'Layout', name: 'Property', meta: { title: '物业管理' }, children: [
    { path: 'complex/complex', name: 'PropertyComplex', component: 'property/complex/index', meta: { title: '物业管理区域备案', filePath: 'property/complex/index' } } ] }
];
(async () => {
  const browser = await chromium.launch({ executablePath: exe, headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 900 } });
  const page = await ctx.newPage();
  page.on('pageerror', e => console.log('PAGEERR', e.message));
  await page.route('**/api/v2.0/**', async (route) => {
    const url = route.request().url();
    const json = (o)=>route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(o)});
    if (url.includes('/system/user/getInfo')) return json({code:200,user:{userName:'t',nickName:'t',terminalType:'A',deptId:1,deptName:'x'},roles:['admin'],permissions:['*:*:*']});
    if (url.includes('/system/profile')) return json({code:200,data:{dept:{deptName:'x'},parentDept:{deptName:'y'}}});
    return json({code:200,data:[],rows:[],total:0});
  });
  await page.addInitScript((rts)=>{
    sessionStorage.setItem('Admin-Token','fake');
    sessionStorage.setItem('routers', JSON.stringify(rts));
    // Install a MutationObserver once body exists to log tags-view create/remove
    window.__tagEvents = [];
    const install = () => {
      if(!document.body) return setTimeout(install, 50);
      const obs = new MutationObserver(() => {
        const present = !!document.querySelector('#tags-view-container');
        const last = window.__tagEvents[window.__tagEvents.length-1];
        if(last !== present){ window.__tagEvents.push(present); }
      });
      obs.observe(document.body, { childList: true, subtree: true });
    };
    setTimeout(install, 100);
  }, routers);
  let ok=false;
  for(let i=0;i<4&&!ok;i++){ await page.goto(BASE+'/#/system/monitor/smartPropertyScreen',{waitUntil:'domcontentloaded',timeout:30000}).catch(()=>{}); await page.waitForTimeout(1500); const bt=(await page.textContent('body').catch(()=>''))||''; if(!/Forbidden nginx/.test(bt)) ok=true; }
  await page.waitForTimeout(4000);
  console.log('EVENTS_INITIAL', JSON.stringify(await page.evaluate(()=>window.__tagEvents)));
  console.log('TAGS_INITIAL', JSON.stringify(await page.$$eval('.tags-view-item',els=>els.map(e=>e.querySelector('.title')?.textContent.trim()))));
  // fullscreen
  await page.evaluate(()=>{document.querySelector('.full-screen')?.click()});
  await page.waitForTimeout(1500);
  console.log('EVENTS_AFTER_FS', JSON.stringify(await page.evaluate(()=>window.__tagEvents)));
  // drill
  await page.evaluate(()=>{const it=[...document.querySelectorAll('.total-item')].find(el=>/物业管理区域总数/.test(el.textContent||'')); it&&it.click();});
  await page.waitForTimeout(4000);
  console.log('URL', page.url());
  console.log('EVENTS_FINAL', JSON.stringify(await page.evaluate(()=>window.__tagEvents)));
  console.log('TAGS_FINAL', JSON.stringify(await page.$$eval('.tags-view-item',els=>els.map(e=>e.querySelector('.title')?.textContent.trim())).catch(()=>[])));
  await browser.close();
})();

